import hashlib, hmac, os

def kdf(password, salt):
    return hashlib.scrypt(password.encode(), salt=salt, n=2**14, r=8, p=1)

SALT = os.urandom(16)
USERS = {"ana@shop.example": (SALT, kdf("correct horse", SALT))}
DUMMY = (os.urandom(16), kdf("unused", SALT))   # for unknown users

def login_vulnerable(email, password):
    if email not in USERS:
        return "No account uses that email address."      # reveals existence
    salt, stored = USERS[email]
    if not hmac.compare_digest(kdf(password, salt), stored):
        return "Wrong password for this account."
    return "ok"

def login_fixed(email, password):
    salt, stored = USERS.get(email, DUMMY)   # same slow work either way
    good = hmac.compare_digest(kdf(password, salt), stored)
    if email in USERS and good:
        return "ok"
    return "Email or password is incorrect."  # one message for both cases

print(login_vulnerable("nobody@shop.example", "x"))
print(login_fixed("nobody@shop.example", "x"))
print(login_fixed("ana@shop.example", "correct horse"))

# Output:
# No account uses that email address.
# Email or password is incorrect.
# ok

from http.cookies import SimpleCookie

def audit(set_cookie):
    c = SimpleCookie()
    c.load(set_cookie)
    for name, m in c.items():
        issues = []
        if not m["secure"]:
            issues.append("no Secure")
        if not m["httponly"]:
            issues.append("no HttpOnly")
        if m["samesite"].lower() not in ("lax", "strict"):
            issues.append("SameSite not Lax/Strict")
        if name.startswith("__Host-") and (m["domain"] or m["path"] != "/"):
            issues.append("__Host- needs Path=/ and no Domain")
        print(f"{name:12} {', '.join(issues) or 'ok'}")

audit("sid=8f3a; Path=/")
audit("__Host-sid=c71e; Path=/; Secure; HttpOnly; SameSite=Lax")

# Output:
# sid          no Secure, no HttpOnly, SameSite not Lax/Strict
# __Host-sid   ok

DOCS = {1001: "ana", 1002: "ben"}
ADMINS = {"root"}

def can_access(user, doc):                    # one check, every method
    return DOCS[doc] == user or user in ADMINS

def app(user, method, path):
    if user is None:
        return 401
    if path == "/admin/users":
        return 200 if user in ADMINS else 403
    doc = int(path.rsplit("/", 1)[1])
    if doc not in DOCS or not can_access(user, doc):
        return 404                            # same answer as "does not exist"
    return 200

for method in ("GET", "DELETE"):
    print(method, "ana", app("ana", method, "/docs/1001"),
          "ben", app("ben", method, "/docs/1001"))

# Output:
# GET ana 200 ben 404
# DELETE ana 200 ben 404

import posixpath

BASE = "/var/www/app/pages"
PAGES = {"home": "home.php", "about": "about.php"}

def vulnerable(page):            # include BASE/<page>.php
    return posixpath.normpath(f"{BASE}/{page}.php")

def fixed(page):                 # the request picks a key, not a path
    name = PAGES.get(page)
    return f"{BASE}/{name}" if name else "404"

for page in ["about", "../config/db", "../../../../tmp/upload_7f2c"]:
    print(f"{page:28} vuln: {vulnerable(page):34} fixed: {fixed(page)}")

